const Autobase = require('autobase')
const Hyperbee = require('hyperbee')
const b4a = require('b4a')

module.exports = { create_automap, open_bee, apply_bee }

function create_automap (options) {
  const { store, bootstrap, base, opts = {} } = options
  const emitter = make_emitter()
  const state = { store: base ? base.store : store, bee: null, bootstrap, opts, base: null }

  // with options.base the bee is one view of an autobase made elsewhere (the vault has the bee + the audit log in one)
  state.base = base || new Autobase(store, bootstrap, {
    valueEncoding: 'json',
    open: handle_autobase_open,
    apply: handle_autobase_apply,
    ackInterval: opts.ack_interval || 1000,
    ackThreshold: opts.ack_threshold || 1,
    fastForward: false
  })

  state.base.on('update', handle_base_update)

  function handle_base_update () {
    if (state.base.view && state.base.view.bee) {
      state.bee = state.base.view.bee
    }
    emitter.emit('update')
  }

  const api = {
    get base () { return state.base },
    get view () { return state.bee },
    get version () { return state.bee ? state.bee.version : 0 },
    get id () { return state.bee ? state.bee.id : null },
    get key () { return state.base ? state.base.key : null },
    get discovery_key () { return state.bee ? state.bee.discoveryKey : null },
    get writable () { return state.base ? state.base.writable : false },
    get readable () { return state.bee ? state.bee.readable : false },
    get core () { return state.bee ? state.bee.core : null },
    on,
    off,
    ready,
    close,
    put,
    del,
    get,
    get_by_seq,
    peek,
    create_read_stream,
    create_history_stream,
    create_diff_stream,
    watch,
    get_and_watch,
    checkout,
    snapshot,
    add_writer,
    remove_writer,
    update,
    sub,
    batch,
    replicate
  }

  return api

  /***************************************
INTERNAL FUNCTIONS
***************************************/
  function handle_autobase_open (store) { return { bee: open_bee(store, opts) } }

  function handle_autobase_apply (nodes, view, base) { return apply_bee(nodes, view.bee, base) }

  function on (event, listener) {
    emitter.on(event, listener)
  }

  function off (event, listener) {
    emitter.off(event, listener)
  }

  async function ready () {
    await state.base.ready()
    await state.base.update()
    if (state.base.view && state.base.view.bee) {
      state.bee = state.base.view.bee
    }
  }

  async function close () {
    if (state.bee) await state.bee.close()
    if (state.base) await state.base.close()
  }

  async function put (key, value) {
    await state.base.append({ type: 'put', data: { key, value } })
    await state.base.update()
    return state.base.latest
  }

  async function del (key) {
    await state.base.append({ type: 'del', data: { key } })
    await state.base.update()
    return state.base.latest
  }

  async function get (key, opts) {
    if (!state.bee) await ready()
    return state.bee.get(key, opts)
  }

  async function get_by_seq (seq, opts) {
    if (!state.bee) await ready()
    return state.bee.getBySeq(seq, opts)
  }

  async function peek (range, opts) {
    if (!state.bee) await ready()
    return state.bee.peek(range, opts)
  }

  function create_read_stream (range, opts) {
    return state.bee.createReadStream(range, opts)
  }

  function create_history_stream (opts) {
    return state.bee.createHistoryStream(opts)
  }

  function create_diff_stream (other_version, range, opts) {
    return state.bee.createDiffStream(other_version, range, opts)
  }

  function watch (range, opts) {
    return state.bee.watch(range, opts)
  }

  async function get_and_watch (key, opts) {
    if (!state.bee) await ready()
    return state.bee.getAndWatch(key, opts)
  }

  function checkout (version, opts) {
    return state.bee.checkout(version, opts)
  }

  function snapshot (opts) {
    return state.bee.snapshot(opts)
  }

  async function add_writer (key, is_indexer = true) {
    const key_str = typeof key === 'string' ? key : b4a.toString(key, 'hex')
    await state.base.append({ type: 'add_writer', data: { key: key_str, is_indexer } })
    await state.base.update()
  }

  async function remove_writer (key) {
    const key_str = typeof key === 'string' ? key : b4a.toString(key, 'hex')
    await state.base.append({ type: 'remove_writer', data: { key: key_str } })
    await state.base.update()
  }

  async function update () {
    return state.base.update()
  }

  // a sub only puts its prefix in front of the key, the same bytes hyperbee's own sub uses (prefix + sep + key),
  // so writes still go through autobase like put / del and reads use hyperbee's sub on the view
  function sub (prefix, opts = {}) {
    const sep = opts.sep || '\x00'
    const full = key => prefix + sep + key
    const view = () => state.bee.sub(prefix, { sep: b4a.from(sep) })
    return {
      put: (key, value) => put(full(key), value),
      del: key => del(full(key)),
      get: async (key, get_opts) => { if (!state.bee) await ready(); return view().get(key, get_opts) },
      create_read_stream: (range, read_opts) => view().createReadStream(range, read_opts),
      batch: () => make_batch(full),
      sub: (child, child_opts) => sub(full(child), child_opts || opts)
    }
  }

  // puts and dels are collected and go into autobase as one append, apply writes them with one bee batch.
  // entries are the collected ones, so they can go into one append together with an entry of another view
  function batch () { return make_batch(key => key) }

  function make_batch (full) {
    const entries = []
    return {
      put: async (key, value) => { entries.push({ type: 'put', data: { key: full(key), value } }) },
      del: async key => { entries.push({ type: 'del', data: { key: full(key) } }) },
      entries,
      flush
    }
    async function flush () {
      if (!entries.length) return
      await state.base.append(entries.splice(0))
      await state.base.update()
    }
  }

  function replicate (stream_or_initiator, opts = {}) {
    return state.store.replicate(stream_or_initiator, opts)
  }
}

/***************************************
GENERAL HELPER FUNCTIONS
***************************************/
// the bee is an autobase view, so every device builds the same bee and autobase can undo it when it reorders.
// open and apply are exported so another autobase can have the bee as one of its views
function open_bee (store, opts = {}) {
  return new Hyperbee(store.get('bee'), {
    keyEncoding: opts.keyEncoding || 'utf-8',
    valueEncoding: opts.valueEncoding || 'json',
    extension: false
  })
}

async function apply_bee (nodes, bee, base) {
  const batch = bee.batch()
  for (const node of nodes) {
    if (node.value === null) continue
    const { type, data } = node.value
    if (type === 'put') {
      await batch.put(data.key, data.value)
    } else if (type === 'del') {
      await batch.del(data.key)
    } else if (type === 'add_writer') {
      await base.addWriter(b4a.from(data.key, 'hex'), { indexer: data.is_indexer })
    } else if (type === 'remove_writer' && base.removeable(b4a.from(data.key, 'hex'))) {
      await base.removeWriter(b4a.from(data.key, 'hex')) // autobase never removes the last indexer
    }
  }
  await batch.flush()
}

/***************************************
MAKE EMITTER
***************************************/
function make_emitter (state = {}) {
  return { on, off, emit }
  function on (type, callback) { (state[type] = state[type] || []).push(callback) }
  function off (type, callback) { (state[type] = state[type] || [])[state[type].indexOf(callback)] = undefined }
  function emit (type, data) {
    function handle_callback (f) {
      return f && f(data)
    }
    return (state[type] = state[type] || []).map(handle_callback)
  }
}
